'use strict';
let sectionComparison=null;
const $=id=>document.getElementById(id);
const localListening=window.ScrunchMixListening?new window.ScrunchMixListening($('bounce-player'),$('listening-status')):null;
$('listen-moment').onclick=()=>{if(current)localListening?.play(current.id,Number($('moment').value),Number($('listening-volume').value));};
$('stop-listening').onclick=()=>{localListening?.stop();$('listening-status').textContent='Stopped.';};
window.addEventListener('pagehide',()=>localListening?.clear());
let token='',current=null,previous=null,appState=null,chatBusy=false,measurementBusy=0,historyRequest=0,connectionBusy=false,workspaceRefresh=null;
const number=(v,unit='',digits=1)=>v==null?'Not measurable':`${v.toFixed(digits)} ${unit}`;
function checkAuthentication(response){if(response.status===403){token='';setChatBusy(chatBusy);throw Error('Mixing needs to reconnect. Use Reconnect; no request will be retried automatically.');}}
async function request(path,body){const measurement=path.startsWith('/api/mix-audit/');if(measurement){measurementBusy++;setChatBusy(chatBusy);}try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Scrunch-Token':token},body:JSON.stringify(body)});checkAuthentication(r);const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data;}finally{if(measurement){measurementBusy--;setChatBusy(chatBusy);}}}
function text(tag,value){const n=document.createElement(tag);n.textContent=value;return n;}
async function refreshHistory(options={}){const sequence=++historyRequest;const response=await fetch('/api/mix-audit/history',options);if(!response.ok)throw Error('Measurements are unavailable. Use Reconnect when Scrunch is ready.');const h=await response.json();if(sequence!==historyRequest)return h;$('storage-status').textContent=h.storageDescription||'';$('clear-measurements').hidden=h.storage!=='memory';$('clear-measurements').disabled=chatBusy||voiceBusy||measurementBusy>0||!h.reports.length;$('history').replaceChildren(...h.reports.map(r=>{const option=text('option',`${r.label||'Untitled bounce'} · ${number(r.durationSeconds,'s')} · ${new Date(r.createdAt*1000).toLocaleString()}`);option.value=r.id;return option;}));$('history').value=current?current.id:(h.selectedId||'');const old=$('compare-history').value;$('compare-history').replaceChildren(...h.reports.filter(r=>r.id!==current?.id).map(r=>{const o=text('option',`${r.label||'Untitled bounce'} · ${number(r.durationSeconds,'s')} · ${new Date(r.createdAt*1000).toLocaleString()}`);o.value=r.id;return o;}));if([...$('compare-history').options].some(o=>o.value===old))$('compare-history').value=old;$('comparison').hidden=!current||!$('compare-history').options.length;return h;}
function discardDisplayedMeasurements(releaseFile=false){localListening?.clear();$('listen-moment').disabled=true;current=null;previous=null;sectionComparison=null;$('report').hidden=true;document.body.classList.remove('has-report');if(releaseFile){$('file').value='';$('file-selected').textContent='No bounce selected';}for(const id of ['metrics','findings','bands','limits','mono-details','moment-stereo','spectral-map','timeline','change-timeline','change-questions','deltas'])$(id).replaceChildren();for(const id of ['name','meta','moment-detail','section-result','compare-note','change-detail'])$(id).textContent='';$('stereo-value').textContent='—';$('stereo-meter').value=0;$('comparison').hidden=true;}
$('clear-measurements').onclick=async()=>{if(chatBusy||voiceBusy||measurementBusy||connectionBusy)return;historyRequest++;const b=$('clear-measurements');b.disabled=true;try{await request('/api/mix-audit/clear',{});discardDisplayedMeasurements(true);$('status').textContent='Measurements cleared. Your source audio and Live Set were unchanged.';await refreshHistory();}catch(e){$('status').textContent=e.message;}finally{b.disabled=!current;}};
$('history').addEventListener('change',async()=>{if(chatBusy||voiceBusy||measurementBusy||connectionBusy||!token)return;try{show(await request('/api/mix-audit/select',{auditId:$('history').value}));$('status').textContent='Saved report selected. Scrunch’s Mixing chat can use these measurements.';}catch(err){$('status').textContent=err.message;}});
function timeline(r){const svg=$('timeline');svg.replaceChildren();const ns='http://www.w3.org/2000/svg';const add=(tag,attrs,value)=>{const n=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));if(value)n.textContent=value;svg.append(n);return n;};const measured=r.rmsWindows||r.windows;const values=measured.map(w=>w.rmsDbFS).filter(v=>v!=null);if(!values.length){add('text',{x:20,y:80,fill:'#a3b5ad'},'No measurable signal');return;}const high=Math.ceil(Math.max(...values)/6)*6,low=Math.min(high-12,Math.floor(Math.min(...values)/6)*6);const x=t=>48+t/r.durationSeconds*835,y=v=>12+(high-Math.max(low,v))/(high-low)*130;
 for(const v of [high,(high+low)/2,low]){add('line',{x1:48,x2:883,y1:y(v),y2:y(v),stroke:'#34413e'});add('text',{x:0,y:y(v)+4,fill:'#a3b5ad','font-size':11},`${v} dB`);}for(const t of [0,r.durationSeconds/2,r.durationSeconds])add('text',{x:x(t),y:169,fill:'#a3b5ad','font-size':11,'text-anchor':t===0?'start':t===r.durationSeconds?'end':'middle'},`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`);
 let points=[];const flush=()=>{if(points.length)add('polyline',{points:points.join(' '),fill:'none',stroke:'#a1ead0','stroke-width':2});points=[];};for(const w of measured){if(w.rmsDbFS==null){flush();continue;}points.push(`${x(w.startSeconds)},${y(w.rmsDbFS)}`,`${x(w.endSeconds)},${y(w.rmsDbFS)}`);}flush();}
function show(r){localListening?.stop();current=r;$('listen-moment').disabled=!localListening?.available(r.id);$('listening-status').textContent=localListening?.available(r.id)?'Ready to hear the selected bounce at its original level. Click Hear this moment; nothing plays automatically.':'Choose its original bounce file here to reconnect listening. Scrunch checks that it matches these measurements.';document.body.classList.add('has-report');$('report').hidden=false;$('name').textContent=r.label||'Untitled bounce';$('meta').textContent=`${r.stage==='unspecified'?'Version type not specified':r.stage} · ${number(r.durationSeconds,'seconds')} · analysed in ${number(r.analysisSeconds,'seconds')}`+(r.liveSource?` · Live bars ${r.liveSource.startBar}–${r.liveSource.endBarExclusive} (end exclusive) · excerpt timestamps start at 0:00`:'');
 if(r.reanalysis)$('meta').textContent+=' · Historical capture, newly analysed; excerpt times start at zero.';timeline(r);showFindings(r);sectionComparison=null;$('section-result').textContent='';$('compare-note').textContent='';$('change-detail').textContent='';$('change-timeline').replaceChildren();$('change-questions').replaceChildren();$('deltas').replaceChildren();visualDetails(r);
 const windows=r.rmsWindows||r.windows,split=windows[Math.floor(windows.length/2)].startSeconds;$('a-start').value=0;$('a-end').value=split;$('b-start').value=split;$('b-end').value=r.durationSeconds;$('sections').querySelector('button').disabled=windows.length<2;if(windows.length<2)$('section-result').textContent='This saved report needs two measured windows for comparison.';$('level-method').textContent=`Average signal level in ${r.rmsWindows?'quarter-second':'three-second (legacy report)'} windows, at the original volume. Gaps mean no measurable signal. This is not an energy or quality score.`;
 $('metrics').replaceChildren();for(const [label,value] of [['Integrated loudness',number(r.whole.integratedLUFS,'LUFS')],['True peak',number(r.whole.truePeakDbTP,'dBTP')],['Loudness range',number(r.whole.loudnessRangeLU,'LU')]]){const card=text('div','');card.className='metric';card.append(text('strong',value),text('span',label));$('metrics').append(card);}
 $('bands').replaceChildren();for(const [name,value] of Object.entries(r.bandFractions)){const row=text('div','');row.className='band';const meter=document.createElement('meter');meter.min=0;meter.max=1;meter.value=value||0;meter.setAttribute('aria-label',`${name} energy share`);row.append(text('span',BAND_LABELS[name]||name),meter,text('span',number(value==null?null:value*100,'%')));$('bands').append(row);}
 $('limits').replaceChildren(...r.limitations.map(v=>text('li',v)));
 refreshHistory().catch(err=>{$('status').textContent=err.message;});
}
$('file').addEventListener('change',async()=>{const file=$('file').files[0];$('file-selected').textContent=file?.name||'No bounce selected';
 if(!current||!localListening||!file||!crypto.subtle)return;
 const selected=current;localListening.stop();$('listen-moment').disabled=true;$('listening-status').textContent='Checking this file against the displayed measurements…';
 try{const matched=await localListening.rememberMatching(selected,file);if(current?.id!==selected.id||$('file').files[0]!==file)return;
  $('listen-moment').disabled=!matched;$('listening-status').textContent=matched?'Exact source file matched. Hear this moment is ready; no new analysis or provider call was made.':'This file differs from the displayed report. Analyse it to create its own measurements; it was not linked to these timestamps.';
 }catch(error){if(current?.id===selected.id)$('listening-status').textContent='This file could not be matched. Analyse it before listening.';}
});
$('upload').addEventListener('submit',async e=>{e.preventDefault();if(chatBusy||voiceBusy||measurementBusy||connectionBusy||!token)return;const file=$('file').files[0];if(!file)return;$('submit').disabled=true;$('status').textContent='Measuring your bounce on this Mac…';
 measurementBusy++;setChatBusy(chatBusy);try{if(file.size>200000000)throw Error('Choose a file up to 200 MB.');const r=await fetch('/api/mix-audit/upload',{method:'POST',headers:{'X-Scrunch-Token':token,'X-File-Name':encodeURIComponent(file.name),'X-Mix-Stage':$('stage').value},body:file});checkAuthentication(r);const result=await r.json();if(!r.ok)throw Error(result.error||'Analysis failed');localListening?.remember(result,file);previous=current;show(result);$('status').textContent='Measured. Audio was not saved by Scrunch.';
 if(previous){const c=await request('/api/mix-audit/compare',{beforeId:previous.id,afterId:current.id});showLocalChanges(c);$('comparison').hidden=false;$('compare-note').textContent=`Compared with ${previous.label||'previous bounce'}: loudness changed ${number(c.rawLoudnessChangeLU,'LU')}. Frequency deltas below account for the loudness difference. ${c.verdict} ${c.alignment}${stereoChangeText(c)}`;$('deltas').replaceChildren();for(const [k,v] of Object.entries(c.loudnessMatchedBandChangeDb)){const row=text('div','');row.className='delta';row.append(text('span',k),text('span',number(v,'dB')));$('deltas').append(row);}}
 }catch(err){$('status').textContent=err.message;}finally{measurementBusy--;setChatBusy(chatBusy);}});
$('sections').addEventListener('submit',async e=>{e.preventDefault();if(!current||chatBusy||voiceBusy||measurementBusy||connectionBusy||!token)return;const selected=current.id;sectionComparison=null;$('section-result').textContent='Measuring requested sections…';try{const [a,b]=await Promise.all(['a','b'].map(x=>request('/api/mix-audit/section',{auditId:current.id,startSeconds:Number($(x+'-start').value),endSeconds:Number($(x+'-end').value)})));if(current?.id!==selected)return;const difference=a.rmsDbFS==null||b.rmsDbFS==null?null:b.rmsDbFS-a.rmsDbFS;sectionComparison={auditId:selected,first:a,second:b,rmsChangeDb:difference,origin:current.liveSource?'Excerpt-relative seconds from the captured audio; song timestamp alignment unverified.':'Elapsed seconds in this bounce; source/session alignment unverified.'};$('section-result').textContent=`Measured ${a.measuredSeconds.map(v=>v.toFixed(3)).join('–')} s (${number(a.coverageFraction*100,'%',1)} coverage) versus ${b.measuredSeconds.map(v=>v.toFixed(3)).join('–')} s (${number(b.coverageFraction*100,'%',1)} coverage). Second section RMS change: ${number(difference,'dB')}. Complete measured blocks only; excluded edges were not estimated. These intervals are available to Mixing chat. This is contrast, not an automatic quality judgement.`;}catch(err){$('section-result').textContent=err.message;}});
$('capture').addEventListener('submit',async e=>{e.preventDefault();if(chatBusy||voiceBusy||measurementBusy||connectionBusy||!token)return;$('capture-submit').disabled=true;$('capture-stop').disabled=false;$('status').textContent='Live is measuring the selected range in real time…';try{const r=await request('/api/mix-audit/capture',{startBar:Number($('start-bar').value),endBar:Number($('end-bar').value)});show(r);$('status').textContent='Main output measured. Playback stopped and capture tracks removed.';}catch(err){$('status').textContent=err.message;}finally{$('capture-stop').disabled=true;setChatBusy(chatBusy);}});
$('capture-stop').addEventListener('click',async()=>{try{$('status').textContent='Stopping measurement…';await request('/api/stop',{});}catch(err){$('status').textContent=err.message;}});
function traceView(data){const box=text('div','');box.append(text('p',data.basis),text('p',data.replayed?'This run replayed a saved decision. The model usage below belongs to the original call.':'These are historical calls, not a fresh analysis.'));
 for(const d of data.decisions){const detail=text('details','');detail.append(text('summary',`Decision ${d.step}: ${d.answer?.step||'unknown'}`),text('p','Model proposal — execution is recorded separately:'),text('blockquote',d.answer?.reply||'No reply saved'),text('p',d.linkBasis));
 if(d.executionError)detail.append(text('p','Execution error: '+d.executionError));
 if(d.executed)detail.append(text('pre',JSON.stringify(d.executed,null,2)));
 const j=d.journal;if(j){detail.append(text('p',`${j.model.model||'Model not recorded'} · ${number(j.elapsedMs==null?null:j.elapsedMs/1000,'seconds')} · ${j.usage?.totalTokenCount??'Unreported'} total tokens. Cost: ${j.costStatus||'not reported'}.`));
 const inputs=text('details','');inputs.append(text('summary','Exact saved input and reply'),text('p',data.exactness),text('pre',JSON.stringify({input:j.input,reply:j.reply,usage:j.usage},null,2)));detail.append(inputs);}
 else detail.append(text('p','Exact model input is unavailable for this decision.'));box.append(detail);}
 for(const c of data.unmatchedLinkedCalls)box.append(text('p',`Linked call ${c.status}: ${c.error||'No matching completed decision was recorded.'}`));
 if(!data.decisions.length)box.append(text('p','No model decision was recorded.'));return box;}
function trialCard(r){const card=text('details','');card.className='trial';const summary=text('summary',''),title=text('span',r.note||'Mix trial'),status=text('span',`${r.status||'unknown'} · historical`);title.className='trial-title';status.className='trial-status';summary.append(title,status);card.append(summary,text('p',`Source: ${r.source}`));
 const source=r.sourceAssociation;if(source){card.append(text('p',source.verifiedSavedSource?`Saved engineer note ${source.commentIndex+1} · ${source.sessionName||'Set not recorded'} · source verified`:'Engineer source association unverified'),text('p',source.basis));const cue=source.cue;if(cue?.cues?.length)card.append(text('p',`Historical timestamp mapping: ${cue.cues.map(c=>`${c.seconds?Number(c.seconds[0]).toFixed(2)+' s · ':''}bar ${c.firstBar}`).join('; ')}. Constant-tempo mapping; current alignment unverified.`));}
 if(source?.originalCue?.cues?.length)card.append(text('p',`Original run timestamp mapping: ${source.originalCue.cues.map(c=>`${c.seconds?Number(c.seconds[0]).toFixed(2)+' s · ':''}bar ${c.firstBar}`).join('; ')}. This is not verified replay alignment.`));
 const inspect=text('button','View model evidence');inspect.type='button';const traceBox=text('div','');card.append(inspect,traceBox);inspect.addEventListener('click',async()=>{inspect.disabled=true;try{const data=await request('/api/mix-engineer/trace',{runId:r.id});traceBox.replaceChildren(traceView(data));inspect.textContent='Model evidence loaded';}catch(err){traceBox.textContent=err.message;inspect.disabled=false;}});
 card.append(text('p',`${r.status}${r.createdAt?' · '+new Date(r.createdAt*1000).toLocaleString():''} · ${r.replayed?'Saved model decision replayed':'Recorded run'}${r.modelCalls!=null?' · '+r.modelCalls+' model calls in this run':''}`));
 if(r.error)card.append(text('p','Recorded outcome: '+r.error));
 for(const t of r.trials){if(t.mainChange){const b=t.mainChange;card.append(text('p',`Measured Main change: ${number(b.changeDb,'dB')} in ${b.loHz}–${b.hiHz} Hz. Change alone does not establish improvement.`));}
 const coverage=t.captureCoverage;
 card.append(text('p',coverage?(coverage.verified?'Capture ranges and lengths checked. Musical timing alignment remains approximate.':'Capture comparison failed or is incomplete; no verified before-and-after result.'):'Capture range verification was not recorded for this historical trial.'));
 if(coverage&&!coverage.verified){const errors=[...(coverage.errors||[]),...(coverage.original?.errors||[]),...(coverage.candidate?.errors||[])];if(errors.length)card.append(text('p',errors.join(' ')));}
 if(t.restoredDuringTrial)card.append(text('p','Original restoration was recorded during this trial.'));
 const a=t.automation;if(a){const detail=text('details','');const verdict=a.requestedValuesPassed===true?'Requested values passed verification':a.requestedValuesPassed===false?'Requested values missed verification':'Requested values remain unverified';detail.append(text('summary',verdict));detail.append(text('p',a.basis));
 if(a.originalCheckPassed&&a.requestedValuesPassed===false)detail.append(text('p','The older recording check passed. The stricter check of the saved values exposes a miss.'));
 const wrap=text('div','');wrap.className='table-scroll';const table=text('table','');const head=text('tr','');for(const label of ['Control','Beat','Requested','Read back','Check'])head.append(text('th',label));const thead=text('thead','');thead.append(head);table.append(thead);const body=text('tbody','');
 for(const p of a.points){const row=text('tr','');for(const value of [p.control,p.beat,`${p.requested} ${p.unit}`,p.readDisplay??'Not recorded',p.withinTolerance===true?'Passed':p.withinTolerance===false?'Missed':'Unverified'])row.append(text('td',value));body.append(row);}table.append(body);wrap.append(table);detail.append(wrap);card.append(detail);}}
 if(r.failedAutomation)card.append(text('p','A failed automation readback was retained with the rollback record.'));
 if(r.rollbackError)card.append(text('p','Restoration needs inspection: '+r.rollbackError));return card;}
async function refreshTrials(){try{const response=await fetch('/api/mix-engineer/evidence');if(!response.ok)throw Error('Trial history is unavailable.');const data=await response.json();$('trials').replaceChildren(...data.reports.map(trialCard));$('trial-status').textContent=(data.reports.length?`${data.reports.length} saved trials.`:'No saved trials yet.')+(data.unreadableReports?` ${data.unreadableReports} records could not be read.`:'');}catch(err){$('trial-status').textContent=err.message;}}
$('refresh-trials').addEventListener('click',refreshTrials);refreshTrials();
async function refreshFeedback(){try{const response=await fetch('/api/mix-engineer/feedback');if(!response.ok)throw Error('Saved engineer feedback is unavailable.');const data=await response.json();$('feedback-basis').textContent=data.association;$('engineer-feedback').replaceChildren();for(const r of data.reports){const group=text('details','');group.append(text('summary',`${r.sourceLabel} · ${r.comments.length} notes · ${r.sessionName||'Set not recorded'}`));for(const [i,row] of r.comments.entries()){const card=text('article','');card.className='finding';card.append(text('h3',`Note ${i+1}`),text('p',row.text),Object.assign(text('p','Source note; current detection, correction and musical acceptance are unproved.'),{className:'muted'}));const ask=text('button','Review this note');ask.type='button';ask.className='secondary';ask.onclick=()=>draft(`Review saved engineer feedback ${r.id}, note ${i+1}, quoted verbatim: “${row.text}” What historical evidence exists, and what would need verification now? No Live change is requested.`);card.append(ask);group.append(card);}$('engineer-feedback').append(group);}if(!data.reports.length)$('feedback-basis').textContent='No saved engineer feedback is registered.';if(data.unreadableReports)$('feedback-basis').textContent+=` ${data.unreadableReports} records could not be verified.`;}catch(e){$('feedback-basis').textContent=e.message;}}
refreshFeedback();
const BAND_LABELS={sub:'Sub · 20–60 Hz',bass:'Bass · 60–200',lowMid:'Low mid · 200–500',mid:'Mid · 500–2k',highMid:'Presence · 2–6k',high:'High · 6–12k',air:'Air · 12–20k'};
const stamp=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
function visualDetails(r){
 $('moment').max=Math.max(0,r.durationSeconds-.001);$('moment').value=0;updateMoment();
 let power=0,side=0,covered=0;
 for(const w of r.windows){if(w.rmsDbFS==null||w.sideFraction==null)continue;const dt=w.endSeconds-w.startSeconds,p=10**(w.rmsDbFS/10)*dt;power+=p;side+=p*w.sideFraction;covered+=dt;}
 const share=power>0?side/power:null;$('stereo-value').textContent=number(share==null?null:share*100,'%',1);$('stereo-meter').value=share??0;
 $('stereo-explanation').textContent=share==null?'No measurable stereo signal.':`Power-weighted side energy over ${number(covered,'seconds')}. Side is the difference between left and right; it is not a quality score or a percentage of perceived width.`;
 $('mono-details').replaceChildren();
 if(!r.stereo)$('mono-details').append(text('p','Left/right correlation was not saved in this report. Mono compatibility remains unmeasured.'));
 else for(const [key,label] of [['broadband','Whole mix'],['lowEnd','Low end · 20–200 Hz']]){const m=r.stereo[key];const row=text('div','');row.className='mono-reading';row.append(text('strong',label));if(!m||m.belowReportingFloor)row.append(text('p','No reportable signal; mono compatibility is unknown.'));else row.append(text('p',`L/R correlation: ${number(m.correlation,'',3)} · Mono: ${m.monoCancelled?'cancels to the measurement floor':number(m.monoChangeDb,'dB',2)}.`));$('mono-details').append(row);}
 $('spectral-map').replaceChildren();
 for(const [key,label] of Object.entries(BAND_LABELS)){
  const row=text('div','');row.className='map-row';row.append(text('span',label));const cells=text('div','');cells.className='map-cells';
  for(const w of r.windows){const value=w.bandFractions[key],cell=text('button','');cell.type='button';cell.className='map-cell';cell.style.background=value==null?'#25333a':`rgba(103,211,177,${.08+.92*Math.sqrt(value)})`;cell.title=`${stamp(w.startSeconds)}–${stamp(w.endSeconds)} · ${label} · ${number(value==null?null:value*100,'%')}`;cell.setAttribute('aria-label',cell.title);cell.onclick=()=>{$('moment').value=w.startSeconds;updateMoment();};cells.append(cell);}
  row.append(cells);$('spectral-map').append(row);
 }
 $('map-end').textContent=stamp(r.durationSeconds);
}
function momentEvidence(){
 if(!current)return null;
 const t=Number($('moment').value),level=(current.rmsWindows||current.windows).find(w=>w.startSeconds<=t&&w.endSeconds>t),spectral=current.windows.find(w=>w.startSeconds<=t&&w.endSeconds>t);
 return {auditId:current.id,requestedSeconds:t,timeOrigin:current.liveSource?'Excerpt-relative; absolute song time unverified':'Supplied bounce start',
  level:level?{windowId:level.id,intervalSeconds:[level.startSeconds,level.endSeconds],rmsDbFS:level.rmsDbFS}:null,
  stereo:spectral?{windowId:spectral.id,intervalSeconds:[spectral.startSeconds,spectral.endSeconds],sideFraction:spectral.sideFraction,broadband:spectral.stereo?.broadband??null,lowEnd:spectral.stereo?.lowEnd??null}:null,
  basis:'Saved measurements, not a current Live reading. Mono is (L+R)/2 versus mean channel power. Independent equal channels normally lose 3.01 dB. Below-reporting-floor signal is unknown; cancellation is not a quality judgement or source-track attribution.'};
}
function updateMoment(){
 const evidence=momentEvidence();if(!evidence)return;
 $('moment-time').textContent=stamp(evidence.requestedSeconds);const stereo=evidence.stereo;
 $('moment-detail').textContent=`${number(evidence.level?.rmsDbFS,'dBFS RMS')} · ${number(stereo?.sideFraction==null?null:stereo.sideFraction*100,'% side')}`;
 $('moment-stereo').replaceChildren();
 if(!stereo){$('moment-stereo').append(text('p','No stereo interval covers this moment.'));return;}
 $('moment-stereo').append(Object.assign(text('p',`Stereo interval: ${stereo.intervalSeconds.map(v=>v.toFixed(3)).join('–')} seconds from ${evidence.timeOrigin.toLowerCase()}.`),{className:'muted'}));
 for(const [key,label] of [['broadband','Whole mix'],['lowEnd','Low end · 20–200 Hz']]){const m=stereo[key],row=text('div','');row.className='mono-reading';row.append(text('strong',label));row.append(text('p',!m||m.belowReportingFloor?'Correlation and mono loss are unmeasured in this interval.':`L/R correlation: ${number(m.correlation,'',3)} · Mono: ${m.monoCancelled?'cancels to the measurement floor':number(m.monoChangeDb,'dB',2)}.`));$('moment-stereo').append(row);}
}

function draft(question){$('engineer-input').value=question;$('engineer-input').focus();$('engineer-status').textContent='Question ready. Send when ready.';}
$('moment').oninput=updateMoment;
$('ask-moment').onclick=()=>{const evidence=momentEvidence();if(evidence)draft(`In selected bounce “${current.label}”, explain this moment in plain language. Quote the measured interval and distinguish the RMS interval from the stereo interval. What does this establish, and what needs listening or individual tracks? No Live change is requested. Exact displayed measurement source: ${JSON.stringify(evidence)}`);};
$('ask-sections').onclick=()=>{if(!current)return;const q=sectionComparison,first=[Number($('a-start').value),Number($('a-end').value)],second=[Number($('b-start').value),Number($('b-end').value)];if(!q||q.auditId!==current.id||first.some((v,i)=>v!==q.first.requestedSeconds[i])||second.some((v,i)=>v!==q.second.requestedSeconds[i])){$('engineer-status').textContent='Measure these section intervals first, then ask about the displayed comparison.';return;}draft(`In selected bounce “${current.label}”, explain this displayed section comparison in plain language. Quote the actual measured coverage and distinguish requested intervals from measured blocks. Silence or missing RMS is unknown, not a zero difference. Does this establish a problem, or do we need listening? No Live change is requested. Exact displayed section evidence: ${JSON.stringify(q)}`);};
for(const b of document.querySelectorAll('[data-question]'))b.onclick=()=>draft(b.dataset.question);
$('compare-saved').onclick=async()=>{if(!current||!$('compare-history').value||chatBusy||voiceBusy||measurementBusy||connectionBusy||!token)return;const id=current.id;$('compare-saved').disabled=true;try{const c=await request('/api/mix-audit/compare',{beforeId:$('compare-history').value,afterId:id});if(current?.id!==id)return;showLocalChanges(c);$('compare-note').textContent=`Selected bounce minus comparison: loudness ${number(c.rawLoudnessChangeLU,'LU')}. Frequency changes below account for the loudness difference. ${c.verdict} ${c.alignment}${stereoChangeText(c)}`;$('deltas').replaceChildren(...Object.entries(c.loudnessMatchedBandChangeDb).map(([k,v])=>{const row=text('div','');row.className='delta';row.append(text('span',BAND_LABELS[k]||k),text('span',number(v,'dB')));return row;}));}catch(e){$('compare-note').textContent=e.message;}finally{setChatBusy(chatBusy);}};

function stereoChangeText(c){const bands=c.stereoChanges?.bands;if(!bands)return '';return ' '+[['broadband','Whole mix'],['lowEnd','Low end']].map(([key,label])=>{const d=bands[key];if(!d?.available)return `${label}: mono change unmeasured.`;const state=x=>x?'cancels to the measurement floor':'does not cancel to the measurement floor';return `${label}: correlation change ${number(d.correlationChange,'',3)}; mono loss change ${number(d.monoChangeDbDifference,'dB')}${d.beforeCancelled!==d.afterCancelled?`; before ${state(d.beforeCancelled)}, after ${state(d.afterCancelled)}`:''}.`;}).join(' ')+' Whole-file descriptors; no musical quality verdict.';}
function showLocalChanges(c){
 const local=c.localRms,svg=$('change-timeline');svg.replaceChildren();$('change-questions').replaceChildren();
 if(!local?.available){$('change-detail').textContent=local?.reason||'Local changes are unavailable for these reports.';return;}
 $('change-detail').textContent=`${number(local.coverageFraction*100,'%',1)} of the common duration has matching ${local.windowSeconds===.25?'quarter-second':'three-second'} measurement intervals. Negative means quieter; positive means louder. ${local.basis}`;
 const rows=local.windows,values=rows.filter(w=>w.changeDb!=null),duration=rows.length?rows[rows.length-1].endSeconds:0;
 if(!duration||!values.length){$('change-detail').textContent+=' No pairs have measurable signal in both files.';return;}
 const ns='http://www.w3.org/2000/svg',add=(tag,attrs,value)=>{const n=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);if(value)n.textContent=value;svg.append(n);};
 const extent=Math.max(2,Math.ceil(Math.max(...values.map(w=>Math.abs(w.changeDb)))/2)*2),x=t=>48+t/duration*835,y=d=>12+(extent-d)/(2*extent)*130;
 for(const d of [-extent,0,extent]){add('line',{x1:48,x2:883,y1:y(d),y2:y(d),stroke:d===0?'#688078':'#34413e'});add('text',{x:0,y:y(d)+4,fill:'#a3b5ad','font-size':11},`${d>0?'+':''}${d} dB`);}
 let points=[];const flush=()=>{if(points.length)add('polyline',{points:points.join(' '),fill:'none',stroke:'#b3d2ef','stroke-width':2});points=[];};
 for(const w of rows){if(w.changeDb==null){flush();continue;}points.push(`${x(w.startSeconds)},${y(w.changeDb)}`,`${x(w.endSeconds)},${y(w.changeDb)}`);}flush();
 for(const t of [0,duration/2,duration])add('text',{x:x(t),y:169,fill:'#a3b5ad','font-size':11,'text-anchor':t===0?'start':t===duration?'end':'middle'},stamp(t));
 for(const [name,w] of [['Most reduced',local.quietestChange],['Most increased',local.loudestChange]]){if(!w)continue;const b=text('button',`${name}: ${stamp(w.startSeconds)} · ${number(w.changeDb,'dB',2)}`);b.type='button';b.className='secondary';b.onclick=()=>draft(`Explain the saved comparison from audit ${c.beforeId} to ${c.afterId}, at ${w.startSeconds.toFixed(3)}–${w.endSeconds.toFixed(3)} seconds: original RMS ${w.beforeRmsDbFS.toFixed(3)} dBFS, selected bounce ${w.afterRmsDbFS.toFixed(3)} dBFS, change ${w.changeDb.toFixed(3)} dB. Does that establish a useful correction? Musical alignment is unverified. No Live change is requested.`);$('change-questions').append(b);}
}

function showFindings(r){
 $('finding-origin').textContent=(r.findingsOrigin||'No saved observations for this report.')+' These observations are available verbatim to your engineer.';
 const cards=(r.findings||[]).map(f=>{const card=text('article','');card.className='finding '+f.status;const head=text('div','');head.className='section-head';head.append(text('h3',f.title),Object.assign(text('span',f.status==='check'?'CHECK / LISTEN':f.status.toUpperCase()),{className:'badge'}));card.append(head,text('p',f.text));if(f.nextStep)card.append(Object.assign(text('p',f.nextStep),{className:'muted'}));const details=text('details','');details.append(text('summary','Show measured evidence'),text('p',`${f.id} · ${f.intervalSeconds.map(t=>t.toFixed(3)).join('–')} s · ${f.basis}`),text('pre',JSON.stringify(f.evidence,null,2)),text('p',f.interpretation));const ask=text('button','Ask about this');ask.type='button';ask.className='secondary';ask.onclick=()=>draft(`Explain finding ${f.id} in the selected bounce ${r.id}: “${f.text}” What does its measured evidence establish, and what still needs listening? This is a question, not a request for a Live change.`);card.append(details,ask);return {card,timed:!!f.evidence?.windowId};});
 $('findings').replaceChildren(...cards.filter(x=>!x.timed).map(x=>x.card));const timed=cards.filter(x=>x.timed);if(timed.length){const group=text('details','');group.className='timed-findings';group.append(text('summary',`Explore ${timed.length} measured intervals to check`),...timed.map(x=>x.card));$('findings').append(group);}
}

let recording=null,voiceRequest=null,voiceEpoch=0,replyAudio=null,voiceBusy=false,captureEpoch=0,voiceSuspended=false;
function setChatBusy(on){chatBusy=on;const busy=on||voiceBusy||measurementBusy>0||connectionBusy||!token;$('send-engineer').disabled=busy;$('dictate').disabled=busy;$('history').disabled=busy;$('clear-measurements').disabled=busy||!current;$('submit').disabled=busy;$('engineer-input').disabled=on||voiceBusy;$('reconnect').disabled=on||voiceBusy||measurementBusy>0||connectionBusy;for(const id of ['capture-submit','compare-saved','compare-history','file','stage'])$(id).disabled=busy;$('sections').querySelector('button').disabled=busy||!current||(current.rmsWindows||current.windows||[]).length<2;}
function addMessage(m,historical=false){const box=text('div','');box.className='message '+(m.role==='user'?'user':'assistant');box.append(Object.assign(text('span',m.role==='user'?'YOU':'SCRUNCH'),{className:'speaker'}),text('div',m.text));if(historical)box.append(text('small',m.previewTruncated?'Saved conversation · historical preview shortened':'Saved conversation · historical reply'));else if(m.timings)box.append(text('small',`${m.model||'Saved engineer'} · ${m.timings.modelCalls??'Unreported'} model calls · ${number((m.timings.interpretationMs??0)/1000,'s interpretation')}`));$('engineerChat').append(box);$('engineerChat').scrollTop=$('engineerChat').scrollHeight;}
function loadConversation(state){const p=state.providers?.find(p=>p.id===state.engineerProvider);$('engineer-model').textContent=p?`${p.name} · ${p.model}`:'Choose an engineer model in Settings.';$('engineerChat').replaceChildren();const rows=(state.engineerChat||[]).filter(m=>m.workspace==='mix').slice(-8);for(const m of rows)addMessage(m,true);if(!rows.length)$('engineerChat').append(text('p','Your questions and the engineer’s replies will appear here.'));$('read-replies').checked=localStorage.getItem('scrunch-mix-voice-replies')==='true';const transcriber=state.voiceEngine||'on-device';$('voice-service').textContent=`Speech input: ${transcriber}. On-device input may fall back to your saved Gemini service if local transcription fails. Voice replies: ${state.voiceSettings?.hasKey?'OpenAI · '+state.voiceSettings.voice:'configure in Settings'}. Cloud transcription, engineer replies and spoken replies use configured API services.`;}
function conversationSetupIssue(){
 const profile=appState?.providers?.find(p=>p.id===appState.engineerProvider);
 if(!profile)return 'Choose your AI engineer in Engineer and voice settings. Your question is still here.';
 if(profile.kind!=='compatible'&&!profile.hasKey)return 'Add this engineer’s API key in Engineer and voice settings. Your question is still here.';
 return '';
}
function transcriptionSetupIssue(){
 const service=appState?.voiceEngine||'on-device';
 if(service==='openai'&&!appState?.voiceSettings?.hasKey)return 'Add an OpenAI voice key in Engineer and voice settings before using Speak.';
 if(service==='gemini'&&!appState?.providers?.some(p=>p.kind==='gemini'&&p.hasKey))return 'Add a Gemini profile with its API key in Engineer and voice settings before using Speak.';
 return '';
}
function stopSpeaking(){voiceEpoch++;voiceRequest?.abort();voiceRequest=null;if(replyAudio){replyAudio.pause();replyAudio.src='';replyAudio=null;}$('stop-speaking').disabled=true;$('voice-dot').classList.remove('active');}
$('stop-speaking').onclick=()=>{stopSpeaking();$('engineer-status').textContent='Voice stopped.';};
$('read-replies').onchange=()=>{voiceSuspended=false;localStorage.setItem('scrunch-mix-voice-replies',String($('read-replies').checked));if(!$('read-replies').checked)stopSpeaking();};
async function speakReply(words){if(voiceSuspended||!$('read-replies').checked||!words)return;if(!appState?.voiceSettings?.hasKey){$('engineer-status').textContent='Text reply available. Add an OpenAI voice key in Engineer and voice settings for spoken replies.';return;}stopSpeaking();const epoch=voiceEpoch;voiceRequest=new AbortController();$('stop-speaking').disabled=false;$('engineer-status').textContent='Preparing voice reply…';try{const r=await fetch('/api/speak',{method:'POST',headers:{'Content-Type':'application/json','X-Scrunch-Token':token},body:JSON.stringify({text:words,speed:1}),signal:voiceRequest.signal});checkAuthentication(r);const d=await r.json();if(!r.ok)throw Error(d.error||'Voice reply failed');if(epoch!==voiceEpoch||!$('read-replies').checked)return;replyAudio=new Audio(`data:${d.mime};base64,${d.audio}`);replyAudio.volume=.7;replyAudio.onended=()=>{if(epoch!==voiceEpoch)return;stopSpeaking();$('engineer-status').textContent='Ready for your next question.';};replyAudio.onerror=()=>{if(epoch!==voiceEpoch)return;stopSpeaking();$('engineer-status').textContent='The text reply is available. Audio playback failed.';};$('voice-dot').classList.add('active');await replyAudio.play();if(epoch===voiceEpoch)$('engineer-status').textContent='Speaking…';}catch(e){if(epoch===voiceEpoch){stopSpeaking();$('engineer-status').textContent='Text reply available. Voice: '+e.message;}}}
async function sendEngineer(){const words=$('engineer-input').value.trim();if(!words||chatBusy||recording||voiceBusy||measurementBusy||connectionBusy||!token||!appState)return;const setupIssue=conversationSetupIssue();if(setupIssue){$('engineer-status').textContent=setupIssue;return;}stopSpeaking();setChatBusy(true);addMessage({role:'user',text:words});$('engineer-input').value='';$('engineer-status').textContent='Your engineer is working…';try{const result=await request('/api/engineer',{text:words,requestId:crypto.randomUUID(),workspace:$('request-workspace').value==='audio-midi'?'session':'mix',auditId:$('request-workspace').value==='audio-midi'?null:current?.id,engineerProvider:appState.engineerProvider});addMessage(result);$('engineer-status').textContent=result.failed?'The engineer reported a failure. Inspect the reply before retrying.':'Reply received.';if(!result.failed)await speakReply(result.speechText??result.text);await refreshTrials();}catch(e){if(!$('engineer-input').value)$('engineer-input').value=words;$('engineer-status').textContent=`${e.message} No automatic retry was made. Check the saved conversation before sending again.`;}finally{setChatBusy(false);}}
$('engineer-form').onsubmit=e=>{e.preventDefault();sendEngineer();};
$('audio-midi').onclick=()=>{
 if(chatBusy||voiceBusy||measurementBusy||connectionBusy)return;
 if($('engineer-input').value.trim()){$('melody-status').textContent='Your draft is still in the chat. Send or clear it before starting an audio-to-MIDI request.';return;}
 $('request-workspace').value='audio-midi';
 $('engineer-input').value='Extract MIDI from the Arrangement audio clip on the selected audio track in Ableton. Keep my original audio. If there is more than one clip, ask me which one.';
 $('engineer-status').textContent='Audio to MIDI: select the source audio track in Ableton, then press Send. This uses your AI engineer and the local transcription model.';
 $('engineer-input').focus();
};
$('open-dream').onclick=async()=>{
 const button=$('open-dream');button.disabled=true;
 try{
  const r=await fetch('/api/mixing-demo/dream-link');const result=await r.json();
  if(!r.ok)throw Error(result.error||'Dream is not available yet.');
  const url=new URL(result.url);if(url.protocol!=='http:'||url.hostname!=='127.0.0.1'||url.port!=='3352')throw Error('Dream returned an unexpected address.');
  $('dream-link').href=url.href;$('dream-link').hidden=false;
  $('melody-status').textContent='Dream is ready. Open it below to record, hear the melody and download MIDI.';
 }catch(e){$('dream-link').hidden=true;$('dream-link').removeAttribute('href');$('melody-status').textContent=e.message+' Check setup in Settings.';}
 finally{button.disabled=false;}
};

// Push to talk: PCM stays in memory; release input tracks before transcription.
function wavBytes(chunks,sr){const count=chunks.reduce((s,c)=>s+c.length,0),buffer=new ArrayBuffer(44+count*2),v=new DataView(buffer);const str=(off,s)=>{for(let i=0;i<s.length;i++)v.setUint8(off+i,s.charCodeAt(i));};str(0,'RIFF');v.setUint32(4,36+count*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,sr,true);v.setUint32(28,sr*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,count*2,true);let p=44;for(const c of chunks)for(const sample of c){const n=Math.max(-1,Math.min(1,sample));v.setInt16(p,n<0?n*32768:n*32767,true);p+=2;}return new Blob([buffer],{type:'audio/wav'});}
async function releaseRecording(r){if(r.released)return;r.released=true;clearTimeout(r.timer);if(r.processor)r.processor.onaudioprocess=null;for(const node of [r.processor,r.source,r.gain]){try{node?.disconnect();}catch{}}for(const track of r.stream.getTracks()){try{track.stop();}catch{}}await r.context.close().catch(()=>{});}
async function pauseAtRecordingLimit(r){if(recording!==r)return;await releaseRecording(r);if(recording!==r)return;$('voice-dot').classList.remove('active');$('dictate').textContent='Send recording';$('engineer-status').textContent='Recording paused at one minute. Send recording asks the engineer; discard cancels.';}
async function finishRecording(discard=false){const r=recording;if(!r)return;const epoch=captureEpoch;recording=null;await releaseRecording(r);if(epoch!==captureEpoch)return;$('voice-dot').classList.remove('active');$('dictate').textContent='Speak';$('cancel-voice').hidden=true;if(discard){r.chunks.length=0;captureEpoch++;voiceBusy=false;setChatBusy(false);$('engineer-status').textContent='Recording discarded.';return;}setChatBusy(false);$('engineer-status').textContent='Transcribing your question…';try{if(r.energy<.003)throw Error('No microphone signal detected. Check your input.');const blob=wavBytes(r.chunks,r.context.sampleRate),encoded=await new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(f.result.split(',')[1]);f.onerror=reject;f.readAsDataURL(blob);});const profile=appState.providers?.find(p=>p.kind==='gemini');const result=await request('/api/transcribe',{provider:profile?.id,mime:'audio/wav',audio:encoded});if(epoch!==captureEpoch||voiceSuspended)return;if(!result.text?.trim())throw Error('No speech was transcribed.');$('engineer-input').value=result.text;voiceBusy=false;setChatBusy(false);await sendEngineer();}catch(e){$('engineer-status').textContent='Speech: '+e.message;}finally{if(epoch===captureEpoch){voiceBusy=false;setChatBusy(false);}}}
$('dictate').onclick=async()=>{if(recording){await finishRecording();return;}if(chatBusy||voiceBusy||measurementBusy||connectionBusy||!token)return;const setupIssue=transcriptionSetupIssue();if(setupIssue){$('engineer-status').textContent=setupIssue;return;}stopSpeaking();voiceSuspended=false;const epoch=++captureEpoch;voiceBusy=true;setChatBusy(false);let stream,context;try{stream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true},video:false});if(epoch!==captureEpoch||voiceSuspended){stream.getTracks().forEach(t=>t.stop());return;}context=new AudioContext({sampleRate:16000});await context.resume();if(epoch!==captureEpoch||voiceSuspended){stream.getTracks().forEach(t=>t.stop());await context.close().catch(()=>{});return;}const source=context.createMediaStreamSource(stream),processor=context.createScriptProcessor(2048,1,1),gain=context.createGain();gain.gain.value=0;recording={stream,context,source,processor,gain,chunks:[],energy:0};const r=recording;processor.onaudioprocess=e=>{if(recording!==r)return;const c=new Float32Array(e.inputBuffer.getChannelData(0));r.chunks.push(c);r.energy=Math.max(r.energy,Math.sqrt(c.reduce((s,x)=>s+x*x,0)/c.length));};source.connect(processor);processor.connect(gain);gain.connect(context.destination);r.timer=setTimeout(()=>pauseAtRecordingLimit(r),60000);$('dictate').disabled=false;$('send-engineer').disabled=true;$('dictate').textContent='Finish & send';$('cancel-voice').hidden=false;$('voice-dot').classList.add('active');$('engineer-status').textContent='Listening · up to one minute. Finish & send asks the engineer; discard cancels.';}catch(e){if(recording?.stream===stream){const r=recording;recording=null;await releaseRecording(r);}else{stream?.getTracks().forEach(t=>t.stop());if(context)await context.close().catch(()=>{});}if(epoch===captureEpoch){voiceBusy=false;setChatBusy(false);$('engineer-status').textContent='Microphone: '+e.message;}}};
$('cancel-voice').onclick=()=>finishRecording(true);
function suspendVoice(){voiceSuspended=true;captureEpoch++;stopSpeaking();if(recording){const r=recording;recording=null;r.chunks.length=0;releaseRecording(r).catch(()=>{});}voiceBusy=false;$('dictate').textContent='Speak';$('cancel-voice').hidden=true;setChatBusy(chatBusy);}
window.addEventListener('pagehide',suspendVoice);
window.addEventListener('scrunch-window-hidden',suspendVoice);
// Reconnection only reads local state. Never repeat an interrupted action or provider call.
function reconnectWorkspace(){
 if(workspaceRefresh)return workspaceRefresh;
 if(chatBusy||voiceBusy||measurementBusy||recording)return Promise.resolve(null);
 connectionBusy=true;setChatBusy(chatBusy);
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),5000);
 workspaceRefresh=(async()=>{try{
  const response=await fetch('/api/mix-audit/workspace',{signal:controller.signal}),state=await response.json();
  if(!response.ok)throw Error(state.error||'Mixing is unavailable. Use Reconnect when Scrunch is ready.');
  if(!state.token)throw Error('Mixing could not authenticate. Use Reconnect to try again.');
  const h=await refreshHistory({signal:controller.signal});
  const expired=!!current&&!h.reports.some(r=>r.id===current.id);
  if(expired){discardDisplayedMeasurements();$('history').value='';}
  if(previous&&!h.reports.some(r=>r.id===previous.id))previous=null;
  if(!appState||token!==state.token)loadConversation(state);
  appState=state;token=state.token;
  $('status').textContent=expired?'Reconnected. The displayed measurements expired; analyse your bounce again. Your question and file selection are kept.':current?'Connected. Your selected measurements are available.':'Connected. Choose a bounce to begin.';
  return h;
 }catch(e){token='';$('status').textContent=e.name==='AbortError'?'Scrunch did not respond within five seconds. Use Reconnect when it is ready.':e.message;return null;}
 finally{clearTimeout(timeout);connectionBusy=false;workspaceRefresh=null;setChatBusy(chatBusy);}})();
 return workspaceRefresh;
}
$('reconnect').onclick=()=>reconnectWorkspace();
window.addEventListener('focus',()=>{voiceSuspended=false;reconnectWorkspace();});
window.addEventListener('online',()=>reconnectWorkspace());

(async()=>{const h=await reconnectWorkspace();if(h?.selectedId)try{show(await request('/api/mix-audit/select',{auditId:h.selectedId}));$('status').textContent='Saved measurements loaded.';}catch(err){$('status').textContent=err.message;}})();
